check(LeanGenericrecords\echo_nat_box($box)->value->isEqualTo(4));
check(LeanGenericrecords\echo_again(new NatBoxAgain($n(4), $n(1)))->value->isEqualTo(4));
check(LeanGenericrecords\echo_text_box(new TextBox($greeting, $n(0)))->value === $greeting);
$left = LeanGenericrecords\echo_left(new LeanGenericrecords\LeftBox($n(5), $n(2)));
$right = LeanGenericrecords\echo_right(new LeanGenericrecords\RightBox($n(6), $n(3)));
check($left instanceof LeanGenericrecords\LeftBox && $left->value->isEqualTo(5));
check($right instanceof LeanGenericrecords\RightBox && $right->count->isEqualTo(3));
$specializedBoxes = LeanGenericrecords\echo_boxes($boxes);
check(count($specializedBoxes) === 3 && $specializedBoxes[2]->value->isEqualTo($huge) && LeanGenericrecords\echo_boxes([]) === []);
$specializedOptional = LeanGenericrecords\echo_optional_boxes(new Some($boxes));
check($specializedOptional instanceof Some && $specializedOptional->value[2]->value->isEqualTo($huge));
check(LeanGenericrecords\echo_optional_boxes(null) === null && LeanGenericrecords\echo_optional_boxes(new Some([]))->value === []);
$specializedNats = LeanGenericrecords\echo_nats([$n(0), $huge]);
check(count($specializedNats) === 2 && $specializedNats[1]->isEqualTo($huge) && LeanGenericrecords\echo_nats([]) === []);
check(LeanGenericrecords\echo_optional_nat(new Some($huge))->value->isEqualTo($huge) && LeanGenericrecords\echo_optional_nat(null) === null);
check(rejected(fn() => LeanGenericrecords\echo_left(new LeanGenericrecords\RightBox($n(5), $n(2)))));
check(rejected(fn() => LeanGenericrecords\echo_boxes([new NatBoxAgain($n(1), $n(0))])));
check(rejected(fn() => LeanGenericrecords\echo_optional_nat(new Some($n(-1)))));
check(LeanGenericrecords\echo_left(new LeanGenericrecords\LeftBox($n(7), $n(0)))->value->isEqualTo(7));
